<?php require_once '../../../includes/config.php'; require_once '../../../includes/db.php'; require_once '../../../includes/auth.php'; require_once '../../../includes/helpers.php'; require_role(['admin']); $pdo = get_pdo(); $page_title = 'Tambah Semester'; $errors = []; $form_data = ['tahun_ajaran' => date('Y') . '/' . (date('Y') + 1), 'tingkatan_semester' => 'ganjil', 'status' => 'nonaktif']; if ($_SERVER['REQUEST_METHOD'] === 'POST') { if (empty($_POST['_csrf']) || !csrf_verify($_POST['_csrf'])) { $errors[] = 'CSRF token tidak valid'; } $form_data['tahun_ajaran'] = trim($_POST['tahun_ajaran'] ?? ''); $form_data['tingkatan_semester'] = $_POST['tingkatan_semester'] ?? 'ganjil'; $form_data['status'] = $_POST['status'] ?? 'nonaktif'; if (empty($form_data['tahun_ajaran'])) { $errors[] = 'Tahun ajaran harus diisi'; } if (!preg_match('/^\d{4}\/\d{4}$/', $form_data['tahun_ajaran'])) { $errors[] = 'Format tahun ajaran harus YYYY/YYYY (contoh: 2024/2025)'; } if (empty($errors)) { try { if ($form_data['status'] === 'aktif') { $stmt = $pdo->prepare("UPDATE semester SET status = 'nonaktif' WHERE status = 'aktif'"); $stmt->execute(); } $stmt = $pdo->prepare("INSERT INTO semester (tahun_ajaran, tingkatan_semester, status) VALUES (?, ?, ?)"); $stmt->execute([$form_data['tahun_ajaran'], $form_data['tingkatan_semester'], $form_data['status']]); flash('success', 'Semester berhasil ditambahkan'); redirect(APP_URL . '/admin/semester/index.php'); exit; } catch (Exception $e) { $errors[] = 'Error: ' . $e->getMessage(); } } } ?> <!DOCTYPE html> <html lang="id"> <head> <meta charset="UTF-8"> <meta name="viewport" content="width=device-width, initial-scale=1.0"> <title><?= h($page_title) ?> - SIAKAD Gallery</title> <link rel="stylesheet" href="<?= APP_URL ?>/assets/css/style.css"> <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.10.0/font/bootstrap-icons.css"> <style> .form-container { background: white; border-radius: 16px; padding: 32px; box-shadow: 0 2px 10px rgba(11, 30, 79, 0.06); max-width: 600px; } .form-group { margin-bottom: 20px; } .form-label { display: block; font-weight: 600; color: #0B1E4F; margin-bottom: 8px; font-size: 14px; } .form-control, .form-select { width: 100%; padding: 10px 14px; border: 1px solid #E4E7EE; border-radius: 8px; font-size: 14px; font-family: inherit; } .form-actions { display: flex; gap: 12px; margin-top: 32px; padding-top: 24px; border-top: 1px solid #E4E7EE; } .btn-secondary { padding: 10px 20px; border-radius: 8px; border: 1px solid #E4E7EE; background: white; color: #2C3A59; text-decoration: none; cursor: pointer; font-weight: 500; } .alert-danger { background: #FFEBEE; border: 1px solid #EF9A9A; color: #C62828; padding: 12px 16px; border-radius: 8px; margin-bottom: 20px; } </style> </head> <body> <div class="app-container"> <?php include '../../../includes/header.php'; ?> <div class="main-content"> <?php include '../../../includes/sidebar.php'; ?> <div class="content-area"> <h1 style="margin-bottom: 24px;"><?= h($page_title) ?></h1> <div class="form-container"> <?php if (!empty($errors)): ?> <div class="alert-danger"> <ul style="margin: 0; padding-left: 20px;"> <?php foreach ($errors as $error): ?> <li><?= h($error) ?></li> <?php endforeach; ?> </ul> </div> <?php endif; ?> <form method="POST"> <input type="hidden" name="_csrf" value="<?= csrf_token() ?>"> <div class="form-group"> <label class="form-label">Tahun Ajaran <span style="color: #E04F5F;">*</span></label> <input type="text" name="tahun_ajaran" class="form-control" value="<?= h($form_data['tahun_ajaran']) ?>" placeholder="2024/2025" required> </div> <div class="form-group"> <label class="form-label">Tingkatan <span style="color: #E04F5F;">*</span></label> <select name="tingkatan_semester" class="form-select" required> <option value="ganjil" <?= $form_data['tingkatan_semester'] === 'ganjil' ? 'selected' : '' ?>>Ganjil</option> <option value="genap" <?= $form_data['tingkatan_semester'] === 'genap' ? 'selected' : '' ?>>Genap</option> </select> </div> <div class="form-group"> <label class="form-label">Status <span style="color: #E04F5F;">*</span></label> <select name="status" class="form-select" required> <option value="nonaktif" <?= $form_data['status'] === 'nonaktif' ? 'selected' : '' ?>>Non-Aktif</option> <option value="aktif" <?= $form_data['status'] === 'aktif' ? 'selected' : '' ?>>Aktif</option> </select> </div> <div class="form-actions"> <button type="submit" class="btn btn-primary"><i class="bi bi-check-circle"></i> Simpan</button> <a href="<?= APP_URL ?>/admin/semester/index.php" class="btn-secondary"><i class="bi bi-x-circle"></i> Batal</a> </div> </form> </div> </div> </div> </div> <?php include '../../../includes/footer.php'; ?> </body> </html>
